INSERT INTO `campaigns` (`id`, `title`, `category`, `story`, `cover_image`, `documents`, `target_amount`, `raised_amount`, `deadline`, `status`, `is_urgent`, `is_featured`, `created_by`, `created_at`, `updated_at`, `deleted_at`, `student_details`, `video_url`, `account_holder_name`, `account_number`, `latitude`, `longitude`, `location_label`, `program_key`, `sdg_tags`) VALUES
(1, 'Education for All', 'Education', 'Help us provide school supplies to 1000 children.', NULL, NULL, '500000.00', '0.00', '2027-12-31 00:00:00', 'approved', 0, 1, 'USR-001', '2026-07-31 20:53:07', '2026-08-04 18:13:44', '2026-08-04 16:34:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2, 'Save Little Aarav', 'Medical', 'Aarav is a 5-year-old bright and cheerful boy who loves playing with his toy cars and dreams of becoming a pilot one day. However, his dreams and life have come to a sudden halt. Recently, he was diagnosed with a severe congenital heart defect that requires urgent open-heart surgery.

His condition is deteriorating rapidly. He gets breathless even while walking a few steps and his energy levels have dropped significantly. The doctors have advised that the surgery needs to be performed within the next few weeks to save his life.

His parents, Ramesh and Priya, belong to a lower-middle-class family. Ramesh works as a daily wage earner and Priya is a homemaker. They have already exhausted all their meager savings and borrowed from friends and family for Aarav''s preliminary tests and medications. 

The estimated cost of the surgery is ₹5,00,000, a sum that is astronomically high for the family. They have nowhere else to turn and are desperately seeking financial help to save their only child. 

Every small contribution will bring Aarav a step closer to a healthy life. Please open your hearts and donate generously to help Aarav get the surgery he urgently needs. Your support can give him a second chance at life.', '["https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?q=80&w=800&auto=format&fit=crop"]', NULL, '500000.00', '0.00', '2026-08-31 00:00:00', 'approved', 1, 0, 'USR-001', '2026-08-01 03:31:41', '2026-08-05 08:44:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'Support Aarav Sharma''s B.Tech Education', 'Education', 'Aarav is a bright student who has secured admission in IIT Delhi but his family cannot afford the fees. Help him achieve his dream of becoming a software engineer.', 'https://images.unsplash.com/photo-1531384441138-2736e62e0919?q=80&w=800&auto=format&fit=crop', NULL, '150000.00', '0.00', '2026-08-31 00:00:00', 'approved', 1, 1, 'USR-001', '2026-08-01 03:31:41', '2026-08-04 18:13:44', NULL, '{"course":"B.Tech Computer Science","institution":"Indian Institute of Technology, Delhi","progressUpdates":["Secured 9.2 CGPA in Semester 3","Completed internship at Tech Mahindra"]}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Help Priya Fight Cancer', 'Medical', 'Priya, a 28-year-old mother, was recently diagnosed with Stage 3 Breast Cancer. Help fund her chemotherapy.', 'https://images.unsplash.com/photo-1584515933487-779824d29309?q=80&w=800&auto=format&fit=crop', NULL, '1500000.00', '1000.00', '2026-08-31 00:00:00', 'approved', 1, 0, 'USR-002', '2026-08-01 03:31:41', '2026-08-14 15:51:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Support Flood Victims in Assam', 'Disaster Relief', 'Devastating floods have displaced thousands. Your contribution will provide food, shelter, and medical kits.', 'https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?q=80&w=800&auto=format&fit=crop', NULL, '2000000.00', '0.00', '2026-08-31 00:00:00', 'approved', 1, 1, 'USR-001', '2026-08-01 03:31:41', '2026-08-04 18:13:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Memorial Fund for Late Mr. Sharma', 'Memorial', 'A sudden tragedy took Mr. Sharma away. We are raising funds to support his wife and two young children.', 'https://images.unsplash.com/photo-1505373877841-8d25f7d46678?q=80&w=800&auto=format&fit=crop', NULL, '1000000.00', '0.00', '2026-08-31 00:00:00', 'approved', 1, 0, 'USR-002', '2026-08-01 03:31:41', '2026-08-04 18:13:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Wheelchair Support for Disabled Children', 'Medical', 'Aiming to provide 50 customized wheelchairs for underprivileged children with mobility challenges.', 'https://images.unsplash.com/photo-1571520667794-ffb4b4556488?q=80&w=800&auto=format&fit=crop', NULL, '800000.00', '0.00', '2026-08-31 00:00:00', 'approved', 0, 0, 'USR-001', '2026-08-01 03:31:41', '2026-08-04 18:13:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Winter Clothes Drive for Homeless', 'Other', 'Help us distribute warm blankets and clothes to the homeless before the harsh winter begins.', 'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?q=80&w=800&auto=format&fit=crop', NULL, '300000.00', '0.00', '2026-08-31 00:00:00', 'approved', 0, 0, 'USR-001', '2026-08-01 03:31:41', '2026-08-04 18:13:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(9, 'Support Priya Patel''s Medical Education', 'Education', 'Priya has cleared NEET with a top rank and got a seat in AIIMS. However, she needs support for her hostel and books. Your donation will help India get a brilliant doctor.', 'https://images.unsplash.com/photo-1544717305-2782549b5136?q=80&w=800&auto=format&fit=crop', NULL, '200000.00', '0.00', '2026-08-31 00:00:00', 'approved', 0, 0, 'USR-002', '2026-08-01 03:31:41', '2026-08-04 20:11:43', '2026-08-04 20:11:43', '{"course":"MBBS","institution":"AIIMS, New Delhi","progressUpdates":["Top 10 in Anatomy practicals","Volunteering at rural health camp"]}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(10, 'Nutrition for Street Children', 'Children', 'We are providing daily nutritious meals to 500 street children in the slums of Mumbai.', 'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?q=80&w=2070&auto=format&fit=crop', NULL, '300000.00', '0.00', '2026-08-31 00:00:00', 'approved', 0, 0, 'USR-002', '2026-08-01 03:31:41', '2026-08-04 20:11:40', '2026-08-04 20:11:40', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(11, 'Shelter for Stray Dogs', 'Animals', 'Help us build a safe shelter and provide medical care for injured stray animals in Delhi.', 'https://images.unsplash.com/photo-1548199973-03cce0bbc87b?q=80&w=2069&auto=format&fit=crop', NULL, '500000.00', '0.00', '2026-08-31 00:00:00', 'approved', 0, 0, 'USR-001', '2026-08-01 03:31:41', '2026-08-04 20:10:43', '2026-08-04 20:10:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
