(4, 'global', 'team', '[{"id":"1","bio":"Sarah brings over 15 years of experience in non-profit management and social development, leading our strategic initiatives globally.","name":"Sarah Johnson","role":"Chief Executive Officer","imageUrl":"/uploads/team/team-1786689458429-893982582.jpg","socialLinks":{"twitter":"#","linkedin":"#"}},{"id":"2","bio":"David oversees our ground operations and ensures that our field teams are equipped and supported to deliver maximum impact.","name":"David Chen","role":"Operations Director","imageUrl":"/uploads/team/team-1787128362505-954788201.jpg","socialLinks":{"linkedin":"#"}},{"id":"3","bio":"Priya is passionate about grassroots development and has successfully launched over 50 community-driven programs.","name":"Priya Sharma","role":"Community Outreach Head","imageUrl":"/uploads/team/team-1787128367636-51275149.jpg","socialLinks":{"twitter":"#","linkedin":"#"}},{"id":"4","bio":"With a background in international finance, Michael ensures our resources are managed transparently and efficiently.","name":"Michael Osei","role":"Financial Controller","imageUrl":"/uploads/team/team-1787128372187-856571213.jpg","socialLinks":{"linkedin":"#"}}]', 'USR-001', '2026-08-01 09:08:17', '2026-08-19 14:02:53'),
(5, 'global', 'careers', '[{"id":"job-1","title":"Project Manager","isActive":true,"vacancies":100,"salaryRange":"Rs. 30,000 - 45,000","qualifications":"Graduate / Post Graduate with project supervision ability"},{"id":"job-2","title":"District Coordinator","isActive":true,"vacancies":250,"salaryRange":"Rs. 25,000 - 35,000","qualifications":"Graduate with coordination and reporting skills"},{"id":"job-3","title":"Block Coordinator","isActive":true,"vacancies":800,"salaryRange":"Rs. 18,000 - 30,000","qualifications":"12th / Graduate with field coordination ability"},{"id":"job-4","title":"Office Assistant","isActive":true,"vacancies":700,"salaryRange":"Rs. 12,000 - 22,000","qualifications":"12th / Graduate with office work knowledge"},{"id":"job-5","title":"Computer Operator","isActive":true,"vacancies":700,"salaryRange":"Rs. 12,000 - 25,000","qualifications":"Computer typing, MS Office, email and internet knowledge"},{"id":"job-6","title":"Accountant","isActive":true,"vacancies":150,"salaryRange":"Rs. 20,000 - 35,000","qualifications":"Commerce background / Tally / accounting knowledge"},{"id":"job-7","title":"Field Officer","isActive":true,"vacancies":2000,"salaryRange":"Rs. 12,000 - 25,000","qualifications":"Field work, public communication and reporting ability"},{"id":"job-8","title":"Social Worker","isActive":true,"vacancies":2500,"salaryRange":"Rs. 12,000 - 22,000","qualifications":"Social service interest, community support and mobilisation skill"},{"id":"job-9","title":"HR Executive","isActive":true,"vacancies":100,"salaryRange":"Rs. 20,000 - 35,000","qualifications":"Graduate / MBA preferred; recruitment and documentation skill"},{"id":"job-10","title":"Community Worker / Volunteer","isActive":true,"vacancies":2700,"salaryRange":"Rs. 12,000 - 18,000","qualifications":"Local area knowledge, service attitude and basic documentation"}]', 'USR-001', '2026-08-01 09:08:17', '2026-08-06 12:58:44'),
