(7, 'global', 'featured_moments', '[{"id":1,"text":"Partnering with State Health Ministry for rural healthcare access","image":"https://images.unsplash.com/photo-1552664730-d307ca884978?q=80&w=2070&auto=format&fit=crop"},{"id":2,"text":"Awarded \\"Best NGO Platform 2026\\" at the National Social Impact Summit","image":"https://images.unsplash.com/photo-1542744173-8e7e53415bb0?q=80&w=2070&auto=format&fit=crop"},{"id":3,"text":"Launch of the \\"Educate Every Child\\" initiative with leading philanthropists","image":"https://images.unsplash.com/photo-1511632765486-a01c80cb2628?q=80&w=2070&auto=format&fit=crop"},{"id":4,"text":"Celebrating our milestone: 10,000 successful campaigns completed","image":"https://images.unsplash.com/photo-1475503572774-15a45e5d60b9?q=80&w=2070&auto=format&fit=crop"},{"id":5,"text":"Inauguration of the free mobile clinic program across 5 states","image":"https://images.unsplash.com/photo-1531545514256-b1400bc00f31?q=80&w=1974&auto=format&fit=crop"}]', 'USR-001', '2026-08-01 11:15:16', '2026-08-06 12:58:44'),
(9, 'global', 'career_notice', '{"publicNotice":"KNT World Welfare Foundation invites applications from eligible, sincere and service-oriented candidates for approximately 10,000 job opportunities for its welfare, education, health awareness, rural development, office administration and field coordination programmes for the year 2026. Interested candidates may submit the application form along with required documents at the Foundation office or through the authorised application process notified by the Foundation.","keyInformation":[{"label":"Age","value":"18 to 35 years"},{"label":"Qualification","value":"10th / 12th / Graduate / Post Graduate / Diploma as per post"},{"label":"Selection","value":"Application screening, document verification and interview"},{"label":"Salary","value":"Post-wise and experience-based, Rs. 12,000 to Rs. 45,000 per month"},{"label":"Work Area","value":"Banda and other project areas as decided by the Foundation"},{"label":"Last Date","value":"____ / ____ / 2026"}]}', 'USR-001', '2026-08-01 12:09:30', '2026-08-05 09:01:34'),
