(109, 'global', 'policies', '[{"id":1786705573448,"type":"Publications","year":"2026","title":"Project Photo Chapters","fileUrl":"/uploads/policies/policy-seed-1786705573448-KNT_Full_Book_Project_Photo_Chapters.pdf","updatedAt":"2026-08-14T11:21:06.147Z","visibility":"public"},{"id":1786705573449,"type":"Publications","year":"2026","title":"Complete Project Book (Print Safe)","fileUrl":"/uploads/policies/policy-seed-1786705573449-KNT_World_Welfare_Foundation_Complete_Project_Book_2026_Improved_300DPI_Print_Safe_No_Cut.pdf","updatedAt":"2026-08-14T11:21:06.174Z","visibility":"public"},{"id":1786705573450,"type":"Publications","year":"2026","title":"Complete Project VIP Photo Filled Book","fileUrl":"/uploads/policies/policy-seed-1786705573450-KNT_World_Welfare_Foundation_Complete_Project_VIP_Photo_Filled_Book.pdf","updatedAt":"2026-08-14T11:21:06.181Z","visibility":"public"},{"id":1786705573451,"type":"Publications","year":"2026","title":"Full Work Project Cost Portfolio","fileUrl":"/uploads/policies/policy-seed-1786705573451-KNT_World_Welfare_Foundation_Full_Work_Project_Cost_Portfolio_2026_Clear_Typing_No_Cut.pdf","updatedAt":"2026-08-14T11:21:06.191Z","visibility":"public"},{"id":1786705573447,"type":"SOP Manual","year":"2026","title":"hii","fileUrl":"/uploads/policies/policy-1786705571536-42588854.jpg","updatedAt":"2026-08-14T11:06:13.448Z","visibility":"public"}]', 'USR-001', '2026-08-14 16:36:13', '2026-08-14 16:51:06'),
(122, 'global', 'csr_page', '{"intro":"KNT World Welfare Foundation is registered for Corporate Social Responsibility activities (CSR00114281). College students can apply for structured internships under our education, community, and documentation programmes in Banda and across our field work.","heading":"CSR & College Internships","highlights":[{"text":"Registered CSR number CSR00114281. Internships sit under our community and education programmes — not paid staff hiring.","title":"CSR Registration"},{"text":"Undergraduate and postgraduate students from recognised colleges. A college ID and a short statement of interest are enough to start.","title":"Who can apply"},{"text":"Pick an opening, submit the student form, and our team will contact shortlisted applicants with dates, reporting location, and joining instructions.","title":"How it works"}]}', NULL, '2026-08-19 16:41:14', '2026-08-19 16:41:14'),
(123, 'global', 'csr_internships', '[{"id":"csr-edu-outreach","seats":8,"title":"Education Outreach Intern","stipend":"Unpaid / certificate + travel support","duration":"6–8 weeks","isActive":true,"location":"Banda, Uttar Pradesh","eligibility":"Any undergraduate / B.Ed / social work student"},{"id":"csr-digital-docs","seats":4,"title":"Documentation & Digital Intern","stipend":"Unpaid / certificate","duration":"6–8 weeks","isActive":true,"location":"Office + remote","eligibility":"Any course; comfort with writing, photos, or basic design"},{"id":"csr-community","seats":6,"title":"Community Development Intern","stipend":"Unpaid / certificate + field support","duration":"8–12 weeks","isActive":true,"location":"Field work around Banda","eligibility":"Social work, rural development, or related courses"}]', NULL, '2026-08-19 16:41:14', '2026-08-19 16:41:14');


-- ----------------------------
-- Table `content_modules`
-- ----------------------------
DROP TABLE IF EXISTS `content_modules`;
CREATE TABLE `content_modules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` enum('certificate','partner','team','blog','gallery','program') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `media` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_published` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
