-- ----------------------------
-- Table `donations`
-- ----------------------------
DROP TABLE IF EXISTS `donations`;
CREATE TABLE `donations` (
  `id` varchar(255) NOT NULL,
  `donor_id` varchar(255) DEFAULT NULL,
  `campaign_id` int DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `tip_amount` decimal(15,2) DEFAULT '0.00',
  `payment_ref` varchar(255) DEFAULT NULL,
  `screenshot_url` varchar(255) DEFAULT NULL,
  `status` enum('pending','verified','failed','refunded') DEFAULT 'pending',
  `donated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `guest_name` varchar(255) DEFAULT NULL,
  `guest_email` varchar(255) DEFAULT NULL,
  `guest_phone` varchar(50) DEFAULT NULL,
  `guest_pan` varchar(20) DEFAULT NULL,
  `guest_address` varchar(500) DEFAULT NULL,
  `guest_city` varchar(100) DEFAULT NULL,
  `guest_state` varchar(100) DEFAULT NULL,
  `guest_pincode` varchar(20) DEFAULT NULL,
  `payment_mode` varchar(50) DEFAULT 'UPI',
  `gateway` varchar(40) DEFAULT NULL,
  `gateway_order_no` varchar(80) DEFAULT NULL,
  `gateway_ref` varchar(80) DEFAULT NULL,
  `gateway_payload` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `donor_id` (`donor_id`),
  KEY `campaign_id` (`campaign_id`),
  KEY `idx_donations_status` (`status`),
  KEY `idx_donations_created` (`created_at`),
  CONSTRAINT `donations_ibfk_1` FOREIGN KEY (`donor_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `donations_ibfk_2` FOREIGN KEY (`campaign_id`) REFERENCES `campaigns` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

