INSERT INTO `mail_templates` (`id`, `template_key`, `name`, `subject`, `html`, `updated_at`) VALUES
(1, 'donation_received', 'Donation received', 'We received your donation — KNT World Welfare Foundation', '<p>Dear {{name}},</p><p>Thank you for donating <strong>INR {{amount}}</strong>{{campaign}}.</p><p>Your payment is under verification. We will email your receipt once our team confirms the transfer.</p><p>Reference: {{id}}</p>', '2026-08-19 11:57:36'),
(2, 'donation_verified', 'Donation verified', 'Donation verified — your receipt is ready', '<p>Dear {{name}},</p><p>Your donation of <strong>INR {{amount}}</strong> has been verified.</p><p>Thank you for supporting our work.</p>', '2026-08-19 11:57:36'),
(3, 'payment_success', 'SBI payment success', 'Payment received — KNT World Welfare Foundation', '<p>Dear {{name}},</p><p>SBI ePay confirmed your donation of <strong>INR {{amount}}</strong>. Your receipt will follow by email.</p><p>Reference: {{id}}</p>', '2026-08-19 11:57:36'),
(4, 'enquiry_alert', 'Enquiry alert', 'New enquiry from {{name}}', '<p>A new contact enquiry was submitted.</p><p><strong>Name:</strong> {{name}}<br/><strong>Email:</strong> {{email}}<br/><strong>Phone:</strong> {{phone}}</p><p>{{message}}</p>', '2026-08-19 11:57:36'),
(5, 'job_application_alert', 'Job application alert', 'New job application: {{name}}', '<p>A new job application was submitted for {{job_title}}.</p><p>{{name}} · {{email}} · {{phone}}</p>', '2026-08-19 11:57:36'),
(6, 'password_reset', 'Password reset', 'Reset your password — KNT World Welfare Foundation', '<p>You requested a password reset.</p><p><a href="{{resetUrl}}">Click here to reset your password</a>. This link expires in 1 hour.</p>', '2026-08-19 11:57:36'),
(7, 'email_verify', 'Email verification', 'Verify your email — KNT World Welfare Foundation', '<p>Dear {{name}},</p><p>Please <a href="{{verifyUrl}}">verify your email</a> to activate your account.</p>', '2026-08-19 11:57:36'),
(8, 'membership_approved', 'Membership approved', 'Membership approved — KNT World Welfare Foundation', '<p>Dear {{name}},</p><p>Your membership is active. Member no: <strong>{{member_no}}</strong>.</p>', '2026-08-19 11:57:36'),
(9, 'volunteer_approved', 'Volunteer approved', 'Volunteer application approved', '<p>Dear {{name}},</p><p>You are now a KNT volunteer ({{volunteer_no}}).</p>', '2026-08-19 11:57:36'),
(10, 'employee_welcome', 'Employee welcome', 'Welcome to KNT World Welfare Foundation', '<p>Dear {{name}},</p><p>You have been onboarded as {{designation}} ({{employee_no}}).</p>', '2026-08-19 11:57:36');


