-- ----------------------------
-- Table `volunteer_assignments`
-- ----------------------------
DROP TABLE IF EXISTS `volunteer_assignments`;
CREATE TABLE `volunteer_assignments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `volunteer_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `scheduled_at` date DEFAULT NULL,
  `hours` decimal(6,1) DEFAULT '0.0',
  `status` enum('assigned','done','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT 'assigned',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ----------------------------
-- Table `volunteer_hours`
-- ----------------------------
DROP TABLE IF EXISTS `volunteer_hours`;
CREATE TABLE `volunteer_hours` (
  `id` int NOT NULL AUTO_INCREMENT,
  `volunteer_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `work_date` date NOT NULL,
  `hours` decimal(6,1) NOT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ----------------------------
-- Table `volunteers`
-- ----------------------------
DROP TABLE IF EXISTS `volunteers`;
CREATE TABLE `volunteers` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `skills` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `availability` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','active','rejected','inactive') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `volunteer_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_card_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hours_total` decimal(8,1) DEFAULT '0.0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_volunteer_no` (`volunteer_no`),
  KEY `idx_volunteers_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

